"""保存通话记录，并把通话发言排除在聊天投影之外。"""

import sqlalchemy as sa
from alembic import op

revision: str = "0003"
down_revision: str | None = "0002"
branch_labels: tuple[str, ...] | None = None
depends_on: tuple[str, ...] | None = None


def upgrade() -> None:
    op.add_column("messages", sa.Column("call_record_id", sa.BigInteger()))
    op.add_column("messages", sa.Column("call_last_seen_at", sa.DateTime(timezone=True)))
    op.add_column("messages", sa.Column("call_duration_ms", sa.BigInteger()))
    op.add_column(
        "prompt_submissions", sa.Column("is_realtime_call", sa.Boolean(), nullable=False, server_default=sa.false())
    )
    op.create_unique_constraint("uq_messages_owned_id", "messages", ["user_id", "conversation_id", "id"])
    op.create_foreign_key(
        "fk_messages_call_record",
        "messages",
        "messages",
        ["user_id", "conversation_id", "call_record_id"],
        ["user_id", "conversation_id", "id"],
        ondelete="CASCADE",
    )
    op.create_index(
        "ix_messages_call_record",
        "messages",
        ["call_record_id", "id"],
        postgresql_where=sa.text("call_record_id IS NOT NULL"),
    )
    op.create_check_constraint(
        op.f("ck_messages_realtime_call"),
        "messages",
        "(subtype IS NOT DISTINCT FROM 'realtime_call') = (call_last_seen_at IS NOT NULL) "
        "AND (call_last_seen_at IS NULL OR (role = 'system' AND call_record_id IS NULL)) "
        "AND (call_duration_ms IS NULL OR (call_last_seen_at IS NOT NULL AND call_duration_ms >= 0))",
    )
    for sql in _AFTER:
        op.execute(sa.schema.DDL(sql))


def downgrade() -> None:
    # 旧 schema 会把通话正文当作聊天历史展示，因此存在通话数据时拒绝降级。
    op.execute(
        sa.schema.DDL("""
        DO $downgrade$
        BEGIN
            IF EXISTS (
                SELECT 1 FROM messages
                WHERE call_record_id IS NOT NULL OR subtype IN ('realtime_call', 'private_compress_summary')
            ) THEN
                RAISE EXCEPTION 'Cannot downgrade a database containing realtime call history';
            END IF;
        END
        $downgrade$;
    """)
    )
    for sql in _BEFORE:
        op.execute(sa.schema.DDL(sql))
    op.drop_constraint(op.f("ck_messages_realtime_call"), "messages", type_="check")
    op.drop_index("ix_messages_call_record", table_name="messages")
    op.drop_constraint("fk_messages_call_record", "messages", type_="foreignkey")
    op.drop_constraint("uq_messages_owned_id", "messages", type_="unique")
    op.drop_column("prompt_submissions", "is_realtime_call")
    op.drop_column("messages", "call_duration_ms")
    op.drop_column("messages", "call_last_seen_at")
    op.drop_column("messages", "call_record_id")


